using FiveSmartFarmCreators.Ichu.Platform.OperationsMonitoring.Domain.Model.ValueObjects;

namespace FiveSmartFarmCreators.Ichu.Platform.OperationsMonitoring.Domain.Model.Aggregates;

/// <summary>
/// A field event observed by an operator or a clinical intervention applied by a veterinarian. Its identifier is
/// the operation identifier generated by the client, so offline retries never create a second record.
/// </summary>
public sealed class LivestockOperation
{
    public const int MaximumObservationLength = 500;
    public const int MaximumProductLength = 120;
    public const int MaximumDoseLength = 60;

    public Guid Id { get; private set; }
    public Guid RanchId { get; private set; }
    public Guid CattleId { get; private set; }
    public OperationType Type { get; private set; }
    public DateTimeOffset OccurredAt { get; private set; }
    public DateTimeOffset ReceivedAt { get; private set; }
    public Guid AuthorId { get; private set; }
    public string? Observation { get; private set; }
    public string? Product { get; private set; }
    public string? Dose { get; private set; }

    private LivestockOperation()
    {
    }

    public LivestockOperation(
        Guid operationId,
        Guid ranchId,
        Guid cattleId,
        OperationType type,
        DateTimeOffset occurredAt,
        Guid authorId,
        string? observation,
        string? product,
        string? dose,
        DateTimeOffset receivedAt)
    {
        if (operationId == Guid.Empty || ranchId == Guid.Empty || cattleId == Guid.Empty || authorId == Guid.Empty)
        {
            throw MonitoringException.InvalidInput("Operation, ranch, animal and author identifiers are required.");
        }

        var normalizedProduct = Normalize(product, MaximumProductLength, "product");
        var normalizedDose = Normalize(dose, MaximumDoseLength, "dose");
        if (!IsClinical(type) && (normalizedProduct is not null || normalizedDose is not null))
        {
            throw MonitoringException.InvalidInput("Only clinical interventions record an administered product or dose.");
        }

        Id = operationId;
        RanchId = ranchId;
        CattleId = cattleId;
        Type = type;
        OccurredAt = occurredAt.ToUniversalTime();
        AuthorId = authorId;
        Observation = Normalize(observation, MaximumObservationLength, "observation");
        Product = normalizedProduct;
        Dose = normalizedDose;
        ReceivedAt = receivedAt.ToUniversalTime();
    }

    public static bool IsClinical(OperationType type) =>
        type is OperationType.Vaccination or OperationType.Treatment or OperationType.Insemination;

    public bool HasSameContentAs(LivestockOperation other) =>
        Id == other.Id &&
        CattleId == other.CattleId &&
        Type == other.Type &&
        OccurredAt == other.OccurredAt &&
        AuthorId == other.AuthorId &&
        Observation == other.Observation &&
        Product == other.Product &&
        Dose == other.Dose;

    private static string? Normalize(string? value, int maximumLength, string field)
    {
        if (string.IsNullOrWhiteSpace(value))
        {
            return null;
        }

        var normalized = value.Trim();
        if (normalized.Length > maximumLength)
        {
            throw MonitoringException.InvalidInput($"The {field} cannot exceed {maximumLength} characters.");
        }

        return normalized;
    }
}
